// plugins/orchestrator/src/model/orchestrator/providers/aws/aws-cloud-formation-templates.ts
class AWSCloudFormationTemplates {
  static getParameterTemplate(p1) {
    return `
  ${p1}:
    Type: String
    Default: ''
`;
  }
  static getSecretTemplate(p1) {
    return `
  ${p1}Secret:
    Type: AWS::SecretsManager::Secret
    Properties:
      Name: '${p1}'
      SecretString: !Ref ${p1}
`;
  }
  static getSecretDefinitionTemplate(p1, p2) {
    return `
          Secrets:
            - Name: '${p1}'
              ValueFrom: !Ref ${p2}Secret
`;
  }
  static insertAtTemplate(template, insertionKey, insertion) {
    const index = template.search(insertionKey) + insertionKey.length + `
`.length;
    template = [template.slice(0, index), insertion, template.slice(index)].join("");
    return template;
  }
  static readTaskCloudFormationTemplate() {
    return TaskDefinitionFormation.formation;
  }
}
