// plugins/steam-deploy/src/parse-steamcmd-output.ts
function parseSteamCmdOutput(output, exitCode) {
  const buildIdMatch = /BuildID\s+(\d+)/.exec(output);
  const buildId = buildIdMatch ? buildIdMatch[1] : "";
  const successConfirmed = /Successfully finished/.test(output);
  const disconnected = /disconnected from steam/i.test(output);
  const errorBuildMatch = /ERROR!.*Build for depot\s+(\d+).*failed/i.exec(output);
  const errorBuild = /ERROR!.*Build for depot.*failed/i.test(output);
  const errorChunks = /ERROR!.*Failed to get list of missing chunks/i.test(output);
  const loginFailed = /Logging in.*FAILED|Login Failure/i.exec(output);
  if (successConfirmed) {
    return { success: true, buildId };
  }
  if (exitCode === 0 && !errorBuild && !errorChunks) {
    return { success: true, buildId };
  }
  const reasons = [];
  if (disconnected)
    reasons.push("Steam connection dropped (request revoked)");
  if (errorChunks)
    reasons.push("failed to get list of missing chunks (lost connection)");
  if (errorBuild) {
    reasons.push(errorBuildMatch ? `depot build reported failure for depot ${errorBuildMatch[1]}` : "depot build reported failure");
  }
  if (loginFailed)
    reasons.push("login failed");
  if (reasons.length === 0) {
    const tail = output.split(`
`).map((line) => line.trim()).filter(Boolean).slice(-5).join(" | ");
    reasons.push(tail ? `exit code ${exitCode}: ${tail}` : `exit code ${exitCode}`);
  }
  return { success: false, buildId: "", failureReason: reasons.join("; ") };
}

