// src/logic/unity/platform-validation/platform-validation.ts
class PlatformValidation {
  static get supportedPlatforms() {
    return ["linux", "win32", "darwin"];
  }
  static checkCompatibility(options) {
    const { hostPlatform, hostOS } = options;
    if (!PlatformValidation.supportedPlatforms.includes(hostPlatform)) {
      throw new Error(`Currently ${hostOS} (${hostPlatform}) is not supported`);
    }
  }
}

// src/logic/unity/native-plugin-compatibility.ts
init_dependencies();
function isWindowsOnlyEditorEntry(entry) {
  if (!entry || typeof entry !== "object")
    return false;
  const { first, second } = entry;
  if (!first || first.Editor !== "Editor")
    return false;
  if (!second)
    return false;
  const enabled = second.enabled;
  const isEnabled = enabled === 1 || enabled === "1" || enabled === true;
  if (!isEnabled)
    return false;
  return second.settings?.OS === "Windows";
}
function parseMetaFile(metaFilePath) {
  let content;
  try {
    content = fsSyncCompat.readFileSync(metaFilePath, "utf-8");
  } catch {
    return null;
  }
  let parsed;
  try {
    parsed = exports_dist.parse(content);
  } catch {
    return null;
  }
  if (!parsed || typeof parsed !== "object")
    return null;
  const pluginImporter = parsed.PluginImporter;
  if (!pluginImporter || typeof pluginImporter !== "object")
    return null;
  const platformData = pluginImporter.platformData;
  if (!Array.isArray(platformData))
    return null;
  const isWindowsOnlyEditor = platformData.some(isWindowsOnlyEditorEntry);
  if (!isWindowsOnlyEditor)
    return null;
  const guid = parsed.guid;
  return { guid: typeof guid === "string" ? guid : undefined };
}
function findDllMetaFiles(dir) {
  let entries;
  try {
    entries = fsSyncCompat.readdirSync(dir, { withFileTypes: true });
  } catch {
    return [];
  }
  const results = [];
  for (const entry of entries) {
    const entryPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      results.push(...findDllMetaFiles(entryPath));
    } else if (entry.isFile() && entry.name.toLowerCase().endsWith(".dll.meta")) {
      results.push(entryPath);
    }
  }
  return results;
}
function scanForWindowsOnlyEditorPlugins(projectPath) {
  const assetsDir = path.join(projectPath, "Assets");
  const metaFiles = findDllMetaFiles(assetsDir);
  const flagged = [];
  for (const metaFilePath of metaFiles) {
    const result = parseMetaFile(metaFilePath);
    if (!result)
      continue;
    const dllPath = metaFilePath.slice(0, -".meta".length);
    const relativePath = path.relative(projectPath, dllPath).split(path.sep).join("/");
    flagged.push({ path: relativePath, guid: result.guid });
  }
  return flagged;
}

// src/command/build/unity-build-command.ts
class UnityBuildCommand extends CommandBase {
  async execute(options) {
    const { hostPlatform, hostOS, engine } = options;
    PlatformValidation.checkCompatibility(options);
    CacheValidation.verify(options);
    if (engine === "unity" && hostOS === "linux" && !options.skipNativePluginCheck) {
      UnityBuildCommand.warnAboutWindowsOnlyEditorPlugins(options);
    }
    const image = new RunnerImageTag(options);
    if (log.isVerbose)
      log.debug("Using image:", image);
    await PlatformSetup.setup(options);
    let stopTail;
    if (options.streamUnityLogs) {
      const projectDir = options.projectPath || options.workspace || process.cwd();
      const explicit = String(options.streamUnityLogPaths || "").split(",").map((s) => s.trim()).filter(Boolean);
      const defaults = [path.join(projectDir, "Builds", "Logs", "Editor.log")];
      stopTail = UnityLogs.streamFiles(explicit.length > 0 ? explicit : defaults);
      log.info("[UnityLogs] Live log streaming started");
    }
    let buildError;
    let buildSucceeded = true;
    try {
      await log.group("Unity build", async () => {
        if (hostPlatform === "darwin") {
          await MacBuilder.run(options);
        } else {
          await Docker.run(image.toString(), options);
        }
      });
    } catch (error) {
      buildError = error;
      buildSucceeded = false;
    } finally {
      if (stopTail) {
        try {
          stopTail();
        } catch {}
      }
    }
    if (options.collectUnityLogs && (!buildSucceeded || options.collectUnityLogsOnSuccess !== false)) {
      try {
        const projectDir = options.projectPath || options.workspace || process.cwd();
        const workspace = options.workspace || projectDir;
        UnityLogs.collect({
          workspace,
          projectPath: projectDir,
          outputDir: options.unityLogsOutputDir || undefined,
          categories: UnityLogs.parseCategories(options.unityLogCategories),
          includeSensitive: !!options.unityLogsIncludeSensitive
        });
      } catch (collectError) {
        log.warning(`[UnityLogs] collection failed: ${collectError.message}`);
      }
    }
    if (buildError)
      throw buildError;
    await Output.setBuildVersion(options.buildVersion);
    await Output.setAndroidVersionCode(options.androidVersionCode);
    return true;
  }
  static warnAboutWindowsOnlyEditorPlugins(options) {
    try {
      const projectDir = options.projectPath || options.workspace || process.cwd();
      const flagged = scanForWindowsOnlyEditorPlugins(projectDir);
      if (flagged.length === 0)
        return;
      const list = flagged.map((plugin) => `  - ${plugin.path}`).join(`
`);
      log.warning(String.dedent`
        [native-plugin-compatibility] ${flagged.length} native plugin(s) are Editor-visible on Windows hosts only,
        but this build is running inside a Linux container - they may be invisible to the Editor here and could
        cause confusing compile errors if referenced unconditionally:
        ${list}
        If this looks wrong, check the plugin's Inspector > Platform Settings > Editor > OS setting. If the plugin
        is meant to be Windows-only and is only ever referenced behind a preprocessor guard (e.g. #if
        UNITY_STANDALONE_WIN), this warning can be safely ignored.
      `);
    } catch (error) {
      if (log.isVerbose)
        log.debug(`[native-plugin-compatibility] scan failed: ${error?.message}`);
    }
  }
  async configureOptions(yargs) {
    await ProjectOptions.configure(yargs);
    await UnityOptions.configure(yargs);
    await VersioningOptions.configure(yargs);
    await BuildOptions.configure(yargs);
    await AndroidOptions.configure(yargs);
    await UnityLogsOptions.configure(yargs);
  }
}

