// src/command-options/docker-test-options.ts
import * as os4 from "node:os";
function defaultDockerMemoryLimit2() {
  const bytesInMegabyte = 1024 * 1024;
  let memoryMultiplier;
  switch (os4.platform()) {
    case "linux":
      memoryMultiplier = 0.95;
      break;
    case "win32":
      memoryMultiplier = 0.8;
      break;
    default:
      memoryMultiplier = 0.75;
      break;
  }
  return `${Math.floor(os4.totalmem() / bytesInMegabyte * memoryMultiplier)}m`;
}

