class HostRunner {
  static buildEnv(options) {
    const { currentWorkDir, cliDistPath, hostPlatform } = options;
    const extraVariables = options.engine === "unity" ? UnityEnvironment.getVariables(options) : [];
    const variables = ImageEnvironmentFactory.getEnvironmentVariables(options, extraVariables);
    const env = {};
    for (const { name, value } of variables) {
      if (value === "" || value === undefined)
        continue;
      env[name] = value.toString();
    }
    if (currentWorkDir)
      env.GITHUB_WORKSPACE = currentWorkDir;
    env.ACTION_FOLDER = cliDistPath;
    const stepsDir = HostRunner.stepsDir(hostPlatform, cliDistPath);
    env.STEPS_DIR = stepsDir;
    env.TEST_RUNNER_ACTION_DIR = path.join(cliDistPath, "test-standalone-scripts");
    const activateLicensePath = path.join(currentWorkDir || process.cwd(), "_activate-license~");
    if (!fsSyncCompat.existsSync(activateLicensePath))
      fsSyncCompat.mkdirSync(activateLicensePath, { recursive: true });
    env.ACTIVATE_LICENSE_PATH = activateLicensePath;
    return env;
  }
  static stepsDir(hostPlatform, cliDistPath) {
    switch (hostPlatform) {
      case "win32":
        return path.join(cliDistPath, "platforms", "windows", "steps");
      case "linux":
      default:
        return path.join(cliDistPath, "platforms", "ubuntu", "steps");
    }
  }
  static async run(options, silent = false) {
    const { cliDistPath, hostPlatform } = options;
    if (hostPlatform !== "linux" && hostPlatform !== "win32") {
      throw new Error(`--local is currently only supported when running on Linux or Windows (got hostPlatform=${hostPlatform}). ` + "macOS already runs natively via MacBuilder without needing --local.");
    }
    log.warning("running the process directly on this host (no Docker)");
    const env = HostRunner.buildEnv(options);
    if (hostPlatform === "win32") {
      const runstepsPath = path.join(cliDistPath, "platforms", "windows", "steps", "runsteps.ps1");
      await HostRunner.runAndDescribeBatchmodeFailures(() => System.run(`powershell -NoProfile -ExecutionPolicy Bypass -File "${runstepsPath}"; exit $LASTEXITCODE`, undefined, { silent, env }));
      return;
    }
    const runstepsPath = path.join(cliDistPath, "platforms", "ubuntu", "steps", "runsteps.sh");
    await HostRunner.runAndDescribeBatchmodeFailures(() => System.run(`bash "${runstepsPath}"`, undefined, {
      silent,
      env
    }));
  }
  static async runAndDescribeBatchmodeFailures(run) {
    try {
      return await run();
    } catch (error) {
      const batchmodeFailure = UnityBatchmodeFailure.describe(error.stdout, error.message);
      if (batchmodeFailure) {
        throw new Error(batchmodeFailure);
      }
      throw error;
    }
  }
}

// src/command/test/unity-test-command.ts
function defaultTestTargetPlatform(hostPlatform = process.platform) {
  switch (hostPlatform) {
    case "win32":
      return "StandaloneWindows";
    case "linux":
    default:
      return "StandaloneLinux64";
  }
}

class UnityTestCommand extends CommandBase {
  async execute(options) {
    if (options.docker) {
      return this.executeDocker(options);
    }
    return this.executeUnityCli(options);
  }
  async executeUnityCli(options) {
    const extraArgs = String(options.unityCliArgs || "").split(" ").map((arg) => arg.trim()).filter(Boolean);
    const available = await UnityCliAdapter.isAvailable();
    if (!available) {
      throw new Error("test: requires Unity's official `unity` CLI binary on PATH " + "(https://docs.unity.com/en-us/unity-cli). Not found in this environment, or pass --docker " + "to run the classic Docker/Hub-image-driven test flow instead.");
    }
    try {
      const result = await UnityCliAdapter.test(extraArgs);
      log.info(result.output);
      return result.success;
    } catch (error) {
      throw new Error(`test: 'unity test' failed: ${error.message}`);
    }
  }
  async executeDocker(options) {
    const { hostPlatform, local } = options;
    if (local) {
      await HostRunner.run({ ...options, runTests: true });
      return true;
    }
    if (hostPlatform === "darwin") {
      throw new Error(`--docker's classic batchmode test flow is not supported on macOS hosts ` + `(got hostPlatform=${hostPlatform}). No Unity Editor Docker images exist for macOS - omit ` + "--docker to use the native `unity test` CLI instead, or add --local to run the same batchmode " + "flow directly against a locally installed Unity.");
    }
    const testOptions = {
      ...options,
      targetPlatform: options.targetPlatform || defaultTestTargetPlatform(hostPlatform)
    };
    const image = new RunnerImageTag(testOptions);
    if (log.isVerbose)
      log.debug("Using image:", image);
    await PlatformSetup.setup(testOptions);
    await log.group("Unity test", async () => {
      await Docker.run(image.toString(), { ...testOptions, runTests: true });
    });
    return true;
  }
  async configureOptions(yargs) {
    await ProjectOptions.configure(yargs);
    await UnityOptions.configure(yargs);
    yargs.default("targetPlatform", defaultTestTargetPlatform());
    await UnityTestOptions.configure(yargs);
    await DockerTestOptions.configure(yargs);
  }
}

// src/plugin/builtin/unity-plugin.ts
var unityPlugin = {
  name: "unity",
  version: "1.0.0",
  engineDetectors: [
    {
      name: "unity",
      detect(projectPath) {
        if (UnityVersionDetector.isUnityProject(projectPath)) {
          const engineVersion = UnityVersionDetector.getUnityVersion(projectPath);
          return { engine: "unity", engineVersion };
        }
        return null;
      }
    }
  ],
  commands: [
    {
      engine: "unity",
      createCommand(command, subCommands) {
        switch (command) {
          case "build":
            return new UnityBuildCommand(command);
          case "activate":
            return new ActivateCommand(command);
          case "return-license":
            return new ReturnLicenseCommand(command);
          case "orchestrate":
            return new UnityOrchestrateCommand(command);
          case "run":
            return new UnityRunCommand(command);
          case "test":
            return new UnityTestCommand(command);
          case "remote":
            switch (subCommands[0]) {
              case "run":
              case "build":
                return new UnityOrchestrateCommand(command);
              default:
                return new NonExistentCommand([command, ...subCommands].join(" "));
            }
          case "logs":
            switch (subCommands[0]) {
              case "collect":
              case "tail":
              case "pull":
              case "fetch":
              case undefined:
              case "":
                return new UnityLogsCommand(command, subCommands[0] || "collect");
              default:
                return new NonExistentCommand([command, ...subCommands].join(" "));
            }
          default:
            return null;
        }
      }
    }
  ]
};

// src/middleware/engine-detection/godot-version-detector.ts
init_dependencies();
import * as nodeFs6 from "node:fs";

class GodotVersionDetector {
  static get versionPattern() {
    return /\d+\.\d+(?:\.\d+)?/;
  }
  static isGodotProject(projectPath) {
    const filePath = path.join(projectPath, "project.godot");
    return fsSyncCompat.existsSync(filePath);
  }
  static getGodotVersion(projectPath) {
    return GodotVersionDetector.read(projectPath);
  }
  static read(projectPath) {
    const filePath = path.join(projectPath, "project.godot");
    if (!fsSyncCompat.existsSync(filePath)) {
      throw new Error(`Godot project file not found at "${filePath}". Have you correctly set the projectPath?`);
    }
    return GodotVersionDetector.parse(nodeFs6.readFileSync(filePath, "utf-8"));
  }
  static parse(projectGodot) {
    const featuresMatch = projectGodot.match(/config\/features\s*=\s*PackedStringArray\("(\d+\.\d+)"/);
    if (featuresMatch) {
      return featuresMatch[1];
    }
    const compatMatch = projectGodot.match(/config\/features\s*=.*?(\d+\.\d+(?:\.\d+)?)/);
    if (compatMatch) {
      return compatMatch[1];
    }
    throw new Error("Failed to parse Godot version from project.godot");
  }
}

// src/command/build/godot-build-command.ts
init_dependencies();

class GodotBuildCommand extends CommandBase {
  async execute(options) {
    const projectPath = options.projectPath || ".";
    const exportPreset = options.exportPreset || "Linux/X11";
    const outputPath = options.outputPath || "build/game";
    const godotImage = options.customImage || `barichello/godot-ci:${options.engineVersion || "4.3"}`;
    const containerProjectPath = options.dockerWorkspacePath || "/github/workspace";
    log.info(`Building Godot project at ${projectPath}`);
    log.info(`Using image: ${godotImage}`);
    const hasExportPresets = fsSyncCompat.existsSync(path.join(projectPath, "export_presets.cfg"));
    await Promise.resolve().then(() => init_model());
    if (hasExportPresets) {
      log.info(`Export preset: ${exportPreset}`);
      await log.group("Godot export", async () => {
        await Docker.run(godotImage, {
          ...options,
          commands: `godot --headless --verbose --path ${containerProjectPath} --export-release "${exportPreset}" ${outputPath}`
        });
      });
    } else {
      log.info("No export_presets.cfg found - validating the project imports cleanly instead of exporting.");
      await log.group("Godot import validation", async () => {
        await Docker.run(godotImage, {
          ...options,
          commands: `godot --headless --verbose --path ${containerProjectPath} --import`
        });
      });
    }
    return true;
  }
  async configureOptions(yargs) {
    await ProjectOptions.configure(yargs);
    yargs.option("exportPreset", {
      alias: "export-preset",
      describe: "Godot export preset name",
      type: "string",
      default: "Linux/X11"
    });
    yargs.option("outputPath", {
      alias: "output-path",
      describe: "Build output path",
      type: "string",
      default: "build/game"
    });
  }
}

